//! Kindle highlights: the e-reader's `My Clippings.txt`
//! (`src/kindle_clippings.rs`, origin `kindle`) and the Kindle app's Export
//! Notebook (`src/kindle_notebook.rs`, origin `kindle_app`). The fixtures are
//! generated by `cargo run -p corpus -- gen-synthetic`
//! (`make synthetic`) under `tests/fixtures/kindle/`, each set with an
//! `expected.json` the generator computed from its own declaration. Offline.

mod common;
use std::path::{Path, PathBuf};

use bookmole::kindle_clippings::{
    ClippingsParse, KindleEntryKind, clippings_path_on, import_kindle_clippings,
    import_kindle_clippings_into, parse_clippings,
};
use bookmole::kindle_notebook::{
    KindleNotebookReport, import_kindle_notebook, parse_notebook, render_notebook,
};
use bookmole::{
    Book, CopyForm, DiagnosticKind, EngineError, ErrorClass, Highlight, HighlightOrigin,
    LearnedFrom, NewCopy, PosKind, Storage, Tenure, same_passages,
};
use common::engine;
use serde_json::Value;

const KINDLE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/kindle");

/// A committed fixture, or `None` with a `SKIPPED:` line; under
/// `BOOKMOLE_REQUIRE_FIXTURES=1` an absent one is a failure.
fn fixture(rel: &str) -> Option<PathBuf> {
    let p = Path::new(KINDLE).join(rel);
    if p.is_file() {
        return Some(p);
    }
    if std::env::var("BOOKMOLE_REQUIRE_FIXTURES").is_ok() {
        panic!("REQUIRE_FIXTURES set but {} is missing", p.display());
    }
    eprintln!(
        "SKIPPED: {} absent; run `make synthetic` to generate it",
        p.display()
    );
    None
}

fn expected(rel: &str) -> Option<Value> {
    let p = fixture(rel)?;
    Some(serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap())
}

const KINDRED: &str = "Kindred (Butler, Octavia E.)";
const GEB_LINE: &str = "Gödel, Escher, Bach: an Eternal Golden Braid (20th Anniversary Edition) (Hofstadter, Douglas R.)";
const MIDDLEMARCH: &str = "Middlemarch (Eliot, George)";
const UNOWNED: &str = "An Unowned Book (Nobody, A.)";

async fn add_book(s: &Storage, title: &str, author: &str) -> i64 {
    let b = Book {
        title: Some(title.into()),
        authors: vec![author.into()],
        ..Default::default()
    };
    s.upsert_book(&b, None).await.unwrap()
}

/// The three library books the clippings fixture names (not the unowned one).
async fn clippings_library(s: &Storage) -> (i64, i64, i64) {
    (
        add_book(s, "Kindred", "Octavia E. Butler").await,
        add_book(
            s,
            "Gödel, Escher, Bach: an Eternal Golden Braid (20th Anniversary Edition)",
            "Douglas R. Hofstadter",
        )
        .await,
        add_book(s, "Middlemarch", "George Eliot").await,
    )
}

async fn rows(s: &Storage, book: i64, origin: HighlightOrigin) -> Vec<Highlight> {
    s.imported_highlights(book, origin).await.unwrap()
}

fn book_expectation<'a>(exp: &'a Value, title_line: &str) -> &'a Value {
    exp["books"]
        .as_array()
        .unwrap()
        .iter()
        .find(|b| b["title_line"] == title_line)
        .unwrap_or_else(|| panic!("no expectation for {title_line}"))
}

fn count(v: &Value) -> usize {
    v.as_u64().unwrap() as usize
}

// ---- My Clippings.txt ------------------------------------------------------------

#[test]
fn the_fixture_parses_as_the_generator_declared_it() {
    let (Some(path), Some(exp)) = (
        fixture("clippings/crlf/My Clippings.txt"),
        expected("clippings/expected.json"),
    ) else {
        return;
    };
    let p = parse_clippings(&std::fs::read_to_string(path).unwrap());
    let base = &exp["base"];
    assert_eq!(
        p.unparsed,
        count(&base["unparsed"]),
        "French + broken entry"
    );
    for b in base["books"].as_array().unwrap() {
        let line = b["title_line"].as_str().unwrap();
        let of = |k: KindleEntryKind| {
            p.entries
                .iter()
                .filter(|e| e.title_line == line && e.kind == k)
                .count()
        };
        assert_eq!(
            of(KindleEntryKind::Bookmark),
            count(&b["bookmarks"]),
            "{line}"
        );
    }
    // The BOM on GEB's title line is gone, and its parentheses kept.
    assert!(p.entries.iter().any(|e| e.title_line == GEB_LINE));
    assert!(p.entries.iter().all(|e| !e.title_line.contains('\u{feff}')));
    // The truncated clipping is kept exactly as the device wrote it.
    assert!(
        p.entries
            .iter()
            .any(|e| e.text == "<You have reached the clipping limit for this item>")
    );
}

#[test]
fn line_endings_and_a_leading_bom_change_nothing() {
    let (Some(crlf), Some(lf)) = (
        fixture("clippings/crlf/My Clippings.txt"),
        fixture("clippings/lf/My Clippings.txt"),
    ) else {
        return;
    };
    let a: ClippingsParse = parse_clippings(&std::fs::read_to_string(crlf).unwrap());
    let b: ClippingsParse = parse_clippings(&std::fs::read_to_string(lf).unwrap());
    assert_eq!(a, b);
    assert!(a.entries.iter().all(|e| !e.text.contains('\r')));
}

#[tokio::test]
async fn importing_the_fixture_matches_three_books_and_reports_the_rest() {
    let (Some(path), Some(exp)) = (
        fixture("clippings/crlf/My Clippings.txt"),
        expected("clippings/expected.json"),
    ) else {
        return;
    };
    let base = &exp["base"];
    let (_tmp, e) = engine().await;
    let s = e.storage();
    let (kindred, geb, middlemarch) = clippings_library(s).await;

    let r = import_kindle_clippings(s, &path, false).await.unwrap();
    assert!(!r.dry_run);
    assert_eq!(r.summary.removed, 0);
    assert_eq!(r.summary.unparsed, count(&base["unparsed"]));
    for (line, book) in [
        (KINDRED, kindred),
        (GEB_LINE, geb),
        (MIDDLEMARCH, middlemarch),
    ] {
        let want = book_expectation(base, line);
        let got = r.books.iter().find(|b| b.title_line == line).unwrap();
        assert_eq!(got.book_id, book, "{line}");
        assert_eq!(got.inserted, count(&want["rows"]), "{line}");
        assert_eq!(got.copy_id, None, "no Kindle copy recorded, none made");
        let stored = rows(s, book, HighlightOrigin::Kindle).await;
        assert_eq!(stored.len(), count(&want["rows"]), "{line}");
        for n in want["notes"].as_array().unwrap() {
            let h = stored
                .iter()
                .find(|h| h.text == n["highlight"].as_str().unwrap())
                .unwrap();
            assert_eq!(h.origin_note.as_deref(), n["note"].as_str(), "{line}");
        }
        assert!(stored.iter().all(|h| h.origin == HighlightOrigin::Kindle));
    }
    let bookmarks: usize = [KINDRED, GEB_LINE, MIDDLEMARCH]
        .iter()
        .map(|l| count(&book_expectation(base, l)["bookmarks"]))
        .sum();
    assert_eq!(r.bookmarks, bookmarks);

    // The unowned title created no book and waits, counted, with a diagnostic.
    assert_eq!(r.unmatched.len(), 1);
    let u = &r.unmatched[0];
    assert_eq!(u.title_line, UNOWNED);
    assert_eq!(u.title, "An Unowned Book");
    assert_eq!(u.authors, vec!["Nobody, A.".to_string()]);
    assert_eq!(u.entries, count(&book_expectation(base, UNOWNED)["rows"]));
    assert_eq!(e.list_books(&Default::default()).await.unwrap().len(), 3);
    let kinds: Vec<&DiagnosticKind> = r.summary.diagnostics.iter().map(|d| &d.kind).collect();
    assert!(kinds.iter().any(|k| matches!(
        k,
        DiagnosticKind::KindleTitleUnmatched { title, entries: 2 } if title == "An Unowned Book"
    )));
    assert!(
        kinds
            .iter()
            .any(|k| matches!(k, DiagnosticKind::KindleEntriesUnparsed { count: 2, .. }))
    );
    // Diagnostics name titles, never a passage.
    for d in &r.summary.diagnostics {
        assert!(!d.to_string().contains("Nobody here owns"), "{d}");
    }

    // Positions, pages and dates as the device gave them.
    let k = rows(s, kindred, HighlightOrigin::Kindle).await;
    let first = k
        .iter()
        .find(|h| h.text.starts_with("The house had kept"))
        .unwrap();
    assert_eq!(first.page, Some(12));
    assert_eq!(first.pos_kind, Some(PosKind::KindleLocation));
    assert_eq!(first.ko_datetime.as_deref(), Some("2025-03-03 10:15:22"));
    let empty = k.iter().find(|h| h.text.is_empty() && h.text_unavailable);
    assert!(
        empty.is_some(),
        "a highlight with no words is kept, flagged"
    );
    let lone = k
        .iter()
        .find(|h| h.origin_note.as_deref() == Some("a note with no highlight"))
        .unwrap();
    assert!(lone.text.is_empty() && !lone.text_unavailable);
    let m = rows(s, middlemarch, HighlightOrigin::Kindle).await;
    let old = m
        .iter()
        .find(|h| h.text.starts_with("An old device"))
        .unwrap();
    assert_eq!(old.ko_datetime.as_deref(), Some("2012-03-30 15:49:00"));
    let page_only = m.iter().find(|h| h.text.starts_with("Page only")).unwrap();
    assert_eq!((page_only.page, page_only.pos_kind), (Some(7), None));
    let g = rows(s, geb, HighlightOrigin::Kindle).await;
    assert!(
        g.iter()
            .any(|h| h.ko_datetime.as_deref() == Some("2025-03-03 22:15:22"))
    );
}

#[tokio::test]
async fn a_second_import_is_all_unchanged_and_keeps_our_annotation() {
    let Some(path) = fixture("clippings/crlf/My Clippings.txt") else {
        return;
    };
    let (_tmp, e) = engine().await;
    let s = e.storage();
    let (kindred, _, _) = clippings_library(s).await;
    let first = import_kindle_clippings(s, &path, false).await.unwrap();
    let h = rows(s, kindred, HighlightOrigin::Kindle).await[0].id;
    s.set_annotation(h, Some("ours")).await.unwrap();

    let again = import_kindle_clippings(s, &path, false).await.unwrap();
    assert_eq!(
        (again.summary.inserted, again.summary.updated),
        (0, 0),
        "{again:?}"
    );
    assert_eq!(again.summary.unchanged, first.summary.inserted);
    let after = rows(s, kindred, HighlightOrigin::Kindle).await;
    assert_eq!(
        after
            .iter()
            .find(|r| r.id == h)
            .unwrap()
            .annotation
            .as_deref(),
        Some("ours")
    );
}

#[tokio::test]
async fn an_appended_file_inserts_the_new_and_refreshes_the_edited_note() {
    let (Some(base), Some(grown), Some(exp)) = (
        fixture("clippings/crlf/My Clippings.txt"),
        fixture("clippings/appended/My Clippings.txt"),
        expected("clippings/expected.json"),
    ) else {
        return;
    };
    let (_tmp, e) = engine().await;
    let s = e.storage();
    let (kindred, _, _) = clippings_library(s).await;
    let first = import_kindle_clippings(s, &base, false).await.unwrap();

    // A dry run predicts the real import exactly and writes nothing.
    let dry = import_kindle_clippings(s, &grown, true).await.unwrap();
    let before: usize = rows(s, kindred, HighlightOrigin::Kindle).await.len();
    let r = import_kindle_clippings(s, &grown, false).await.unwrap();
    assert_eq!(
        before,
        count(&book_expectation(&exp["base"], KINDRED)["rows"])
    );
    assert!(dry.dry_run);
    assert_eq!(
        (
            dry.summary.inserted,
            dry.summary.updated,
            dry.summary.unchanged
        ),
        (r.summary.inserted, r.summary.updated, r.summary.unchanged)
    );

    assert_eq!(r.summary.inserted, count(&exp["appended"]["inserted"]));
    assert_eq!(r.summary.updated, count(&exp["appended"]["updated"]));
    assert_eq!(
        r.summary.unchanged,
        first.summary.inserted - r.summary.updated
    );
    assert_eq!(r.summary.removed, 0);
    let k = rows(s, kindred, HighlightOrigin::Kindle).await;
    let host = k
        .iter()
        .find(|h| h.text.starts_with("The house had kept"))
        .unwrap();
    assert_eq!(
        host.origin_note.as_deref(),
        Some("first thought, third draft")
    );
}

#[tokio::test]
async fn a_highlight_gone_from_the_file_stays_here() {
    // The device's log never forgets, so neither does the import: a shorter
    // file (as if entries had been deleted from it) removes nothing.
    let Some(path) = fixture("clippings/crlf/My Clippings.txt") else {
        return;
    };
    let (tmp, e) = engine().await;
    let s = e.storage();
    let (kindred, _, _) = clippings_library(s).await;
    import_kindle_clippings(s, &path, false).await.unwrap();
    let n = rows(s, kindred, HighlightOrigin::Kindle).await.len();
    let short = tmp.path().join("My Clippings.txt");
    std::fs::write(&short, "").unwrap();
    let r = import_kindle_clippings(s, &short, false).await.unwrap();
    assert_eq!(r.summary.removed, 0);
    assert_eq!(rows(s, kindred, HighlightOrigin::Kindle).await.len(), n);
}

#[tokio::test]
async fn an_unmatched_title_can_be_attached_by_hand() {
    let Some(path) = fixture("clippings/crlf/My Clippings.txt") else {
        return;
    };
    let (_tmp, e) = engine().await;
    let s = e.storage();
    let target = add_book(s, "Something Else Entirely", "Someone").await;
    let r = import_kindle_clippings_into(s, &path, UNOWNED, target, false)
        .await
        .unwrap();
    assert_eq!(r.books.len(), 1);
    assert_eq!(r.books[0].book_id, target);
    assert_eq!(r.summary.inserted, 2);
    assert!(r.unmatched.is_empty());
    assert_eq!(rows(s, target, HighlightOrigin::Kindle).await.len(), 2);

    let missing = import_kindle_clippings_into(s, &path, UNOWNED, 9_999, false).await;
    assert!(matches!(missing, Err(EngineError::NotFound(_))));
}

#[tokio::test]
async fn copy_id_only_when_one_copy_is_plausibly_the_kindles() {
    let (tmp, e) = engine().await;
    let s = e.storage();
    let book = add_book(s, "Kindred", "Octavia E. Butler").await;
    let path = tmp.path().join("My Clippings.txt");
    let clip = |loc: u32| {
        format!(
            "Kindred (Butler, Octavia E.)\r\n- Your Highlight on Location {loc} | Added on Monday, March 3, 2025 10:15:22 AM\r\n\r\nWords at {loc}.\r\n==========\r\n"
        )
    };

    // A print copy is not the Kindle's.
    s.create_copy(&NewCopy::new(
        book,
        Some(CopyForm::Print),
        Tenure::Own,
        LearnedFrom::User,
    ))
    .await
    .unwrap();
    std::fs::write(&path, clip(1)).unwrap();
    let r = import_kindle_clippings(s, &path, false).await.unwrap();
    assert_eq!(r.books[0].copy_id, None);

    let mut app = NewCopy::new(book, Some(CopyForm::App), Tenure::Own, LearnedFrom::User);
    app.app = Some("Kindle".into());
    let kindle = s.create_copy(&app).await.unwrap().id;
    std::fs::write(&path, clip(2)).unwrap();
    let r = import_kindle_clippings(s, &path, false).await.unwrap();
    assert_eq!(r.books[0].copy_id, Some(kindle));
    let stored = rows(s, book, HighlightOrigin::Kindle).await;
    assert_eq!(
        stored
            .iter()
            .find(|h| h.text == "Words at 2.")
            .unwrap()
            .copy_id,
        Some(kindle)
    );
    assert_eq!(
        stored
            .iter()
            .find(|h| h.text == "Words at 1.")
            .unwrap()
            .copy_id,
        None
    );

    // Two candidates: not ours to choose.
    s.create_copy(&NewCopy::new(
        book,
        Some(CopyForm::File),
        Tenure::Own,
        LearnedFrom::Kindle,
    ))
    .await
    .unwrap();
    std::fs::write(&path, clip(3)).unwrap();
    let r = import_kindle_clippings(s, &path, false).await.unwrap();
    assert_eq!(r.books[0].copy_id, None);
    assert_eq!(
        s.copies_for_book(book).await.unwrap().len(),
        3,
        "none created"
    );
}

#[tokio::test]
async fn an_unreadable_file_is_a_diagnostic() {
    let (tmp, e) = engine().await;
    let s = e.storage();
    let class_of =
        |r: &bookmole::kindle_clippings::KindleClippingsReport| match &r.summary.diagnostics[..] {
            [d] => match d.kind {
                DiagnosticKind::KindleClippingsUnreadable { class, .. } => class,
                ref k => panic!("{k:?}"),
            },
            other => panic!("{other:?}"),
        };

    let missing = import_kindle_clippings(s, &tmp.path().join("nope.txt"), false)
        .await
        .unwrap();
    assert_eq!(class_of(&missing), ErrorClass::Io);

    let binary = tmp.path().join("binary.txt");
    std::fs::write(&binary, b"Kindred\x00\x01\x02").unwrap();
    let r = import_kindle_clippings(s, &binary, false).await.unwrap();
    assert_eq!(class_of(&r), ErrorClass::Decode);

    // Sparse: past the cap without writing 32 MB.
    let huge = tmp.path().join("huge.txt");
    std::fs::File::create(&huge)
        .unwrap()
        .set_len(bookmole::kindle_clippings::MAX_FILE_BYTES + 1)
        .unwrap();
    let r = import_kindle_clippings(s, &huge, false).await.unwrap();
    assert_eq!(class_of(&r), ErrorClass::Other);
    assert_eq!(r.summary.inserted, 0);
}

#[test]
fn the_clippings_file_is_found_on_a_mount_whatever_its_case() {
    let tmp = tempfile::tempdir().unwrap();
    assert_eq!(clippings_path_on(tmp.path()), None);
    std::fs::create_dir(tmp.path().join("Documents")).unwrap();
    assert_eq!(clippings_path_on(tmp.path()), None);
    let file = tmp.path().join("Documents").join("my clippings.TXT");
    std::fs::write(&file, "kindle").unwrap();
    // On a case-insensitive volume the exact spelling resolves too; either way
    // it is this file.
    let found = clippings_path_on(tmp.path()).expect("found");
    assert_eq!(
        found.to_string_lossy().to_lowercase(),
        file.to_string_lossy().to_lowercase()
    );
    assert_eq!(std::fs::read_to_string(found).unwrap(), "kindle");
}

/// What `Engine::find_kindle_clippings` does over `mount_roots()`, over temp
/// roots instead: one file per volume that has one, one level deep, a
/// symlinked volume skipped, a missing root ignored, sorted.
#[test]
fn clippings_are_found_on_each_volume_under_the_roots_and_nowhere_else() {
    let tmp = tempfile::tempdir().unwrap();
    let root = tmp.path().join("Volumes");
    let kindle = |name: &str| {
        let docs = root.join(name).join("documents");
        std::fs::create_dir_all(&docs).unwrap();
        let file = docs.join("My Clippings.txt");
        std::fs::write(&file, "kindle").unwrap();
        file
    };
    let b = kindle("Kindle B");
    let a = kindle("Kindle A");
    // A volume with no clippings, and one nested too deep to count.
    std::fs::create_dir_all(root.join("USB").join("documents")).unwrap();
    std::fs::create_dir_all(root.join("Deep").join("inner").join("documents")).unwrap();
    std::fs::write(root.join("Deep/inner/documents/My Clippings.txt"), "kindle").unwrap();
    #[cfg(unix)]
    std::os::unix::fs::symlink(root.join("Kindle A"), root.join("Alias")).unwrap();

    let found = bookmole::device::kindle_clippings_on(&[root.clone(), tmp.path().join("absent")]);
    assert_eq!(found, vec![a, b]);
}

/// The facade re-checks a path it is handed: absent is `NotFound`, the wrong
/// kind of file or a folder is `InvalidInput`, and a file that is there goes
/// through to the importer.
#[tokio::test]
async fn the_facade_refuses_a_path_that_is_not_the_right_file() {
    let Some(clippings) = fixture("clippings/crlf/My Clippings.txt") else {
        return;
    };
    let Some(notebook) = fixture("notebook/remains.html") else {
        return;
    };
    let (tmp, e) = engine().await;
    let s = e.storage();
    let (kindred, _, _) = clippings_library(s).await;

    let gone = tmp.path().join("My Clippings.txt");
    assert!(matches!(
        e.import_kindle_clippings(&gone, true).await,
        Err(EngineError::NotFound(_))
    ));
    assert!(matches!(
        e.import_kindle_clippings(&notebook, true).await,
        Err(EngineError::InvalidInput(_))
    ));
    assert!(matches!(
        e.import_kindle_notebook(&clippings, None, true).await,
        Err(EngineError::InvalidInput(_))
    ));
    let folder = tmp.path().join("folder.txt");
    std::fs::create_dir_all(&folder).unwrap();
    assert!(matches!(
        e.attach_kindle_title(&folder, UNOWNED, kindred, true).await,
        Err(EngineError::InvalidInput(_))
    ));

    let r = e.import_kindle_clippings(&clippings, false).await.unwrap();
    assert_eq!(r.books.len(), 3);
    assert_eq!(r.unmatched.len(), 1);
    let attached = e
        .attach_kindle_title(&clippings, UNOWNED, kindred, false)
        .await
        .unwrap();
    assert_eq!(attached.summary.inserted, 2);
    let book = add_book(s, "The Remains of the Day", "Kazuo Ishiguro").await;
    let n = e
        .import_kindle_notebook(&notebook, None, false)
        .await
        .unwrap();
    assert_eq!(n.book_id, Some(book));
}

// ---- the Kindle app's Export Notebook ---------------------------------------------

#[test]
fn the_notebook_parses_as_the_generator_declared_it() {
    let (Some(path), Some(exp)) = (
        fixture("notebook/remains.html"),
        expected("notebook/expected.json"),
    ) else {
        return;
    };
    let exp = &exp["remains"];
    let p = parse_notebook(&std::fs::read_to_string(path).unwrap());
    assert!(p.recognised);
    assert_eq!(p.title.as_deref(), exp["title"].as_str());
    assert_eq!(
        p.authors,
        vec![exp["authors"][0].as_str().unwrap().to_string()]
    );
    assert_eq!(p.unparsed, count(&exp["unparsed"]));
    let highlights: Vec<_> = p
        .entries
        .iter()
        .filter(|e| e.kind == KindleEntryKind::Highlight)
        .collect();
    assert_eq!(highlights.len(), count(&exp["highlights"]));
    for (i, h) in highlights.iter().enumerate() {
        assert_eq!(h.color.as_deref(), exp["colors"][i].as_str(), "colour {i}");
        assert_eq!(h.text, exp["texts"][i].as_str().unwrap(), "text {i}");
        assert_eq!(
            h.chapter.as_deref(),
            exp["chapters"][i].as_str(),
            "chapter {i}"
        );
        assert_eq!(
            h.page.as_deref().and_then(|p| p.parse::<u64>().ok()),
            exp["pages"][i].as_u64(),
            "page {i}"
        );
        assert_eq!(
            h.location.map(|l| l.as_given()).as_deref(),
            exp["locations"][i].as_str(),
            "location {i}"
        );
    }
    assert_eq!(
        p.entries
            .iter()
            .filter(|e| e.kind == KindleEntryKind::Bookmark)
            .count(),
        count(&exp["bookmarks"])
    );
}

#[tokio::test]
async fn the_notebook_imports_into_its_matched_book_and_again_unchanged() {
    let (Some(path), Some(exp)) = (
        fixture("notebook/remains.html"),
        expected("notebook/expected.json"),
    ) else {
        return;
    };
    let exp = &exp["remains"];
    let (_tmp, e) = engine().await;
    let s = e.storage();
    let book = add_book(s, "The Remains of the Day", "Kazuo Ishiguro").await;

    let dry = import_kindle_notebook(s, &path, None, true).await.unwrap();
    assert!(rows(s, book, HighlightOrigin::KindleApp).await.is_empty());
    let r = import_kindle_notebook(s, &path, None, false).await.unwrap();
    assert_eq!(dry.summary.inserted, r.summary.inserted);
    assert_eq!(r.book_id, Some(book));
    assert_eq!(r.entries, count(&exp["rows"]));
    assert_eq!(r.summary.inserted, count(&exp["rows"]));
    assert_eq!(r.bookmarks, count(&exp["bookmarks"]));
    assert_eq!(r.summary.unparsed, count(&exp["unparsed"]));
    assert!(r.summary.diagnostics.iter().any(|d| matches!(
        d.kind,
        DiagnosticKind::KindleEntriesUnparsed { count: 1, .. }
    )));

    let stored = rows(s, book, HighlightOrigin::KindleApp).await;
    assert_eq!(stored.len(), count(&exp["rows"]));
    for n in exp["notes"].as_array().unwrap() {
        let h = stored
            .iter()
            .find(|h| h.text == n["highlight"].as_str().unwrap())
            .unwrap();
        assert_eq!(h.origin_note.as_deref(), n["note"].as_str());
    }
    for lone in exp["lone"].as_array().unwrap() {
        assert!(
            stored
                .iter()
                .any(|h| h.text.is_empty() && h.origin_note.as_deref() == lone.as_str())
        );
    }
    let yellow = stored
        .iter()
        .find(|h| h.text.starts_with("A journey"))
        .unwrap();
    assert_eq!(yellow.page, Some(3));
    assert_eq!(yellow.pos_kind, Some(PosKind::KindleLocation));
    assert_eq!(yellow.ko_datetime, None, "the export carries no dates");

    let again = import_kindle_notebook(s, &path, None, false).await.unwrap();
    assert_eq!((again.summary.inserted, again.summary.updated), (0, 0));
    assert_eq!(again.summary.unchanged, count(&exp["rows"]));
}

#[tokio::test]
async fn an_unmatched_notebook_creates_nothing_and_says_which_book_it_is() {
    let (Some(path), Some(exp)) = (
        fixture("notebook/unowned.html"),
        expected("notebook/expected.json"),
    ) else {
        return;
    };
    let (_tmp, e) = engine().await;
    let s = e.storage();
    add_book(s, "The Remains of the Day", "Kazuo Ishiguro").await;
    let r: KindleNotebookReport = import_kindle_notebook(s, &path, None, false).await.unwrap();
    assert_eq!(r.book_id, None);
    assert_eq!(r.title.as_deref(), exp["unowned"]["title"].as_str());
    assert_eq!(r.authors, vec!["Nobody, A.".to_string()]);
    assert_eq!(r.entries, count(&exp["unowned"]["rows"]));
    assert_eq!(r.summary.inserted, 0);
    assert!(r.summary.diagnostics.iter().any(|d| matches!(
        &d.kind,
        DiagnosticKind::KindleNotebookUnmatched { title: Some(t), .. } if t == "A Book Nobody Owns"
    )));
    assert_eq!(e.list_books(&Default::default()).await.unwrap().len(), 1);

    // The frontend's answer: this book.
    let chosen = add_book(s, "Mine After All", "Me").await;
    let r = import_kindle_notebook(s, &path, Some(chosen), false)
        .await
        .unwrap();
    assert_eq!(r.book_id, Some(chosen));
    assert_eq!(r.summary.inserted, 1);
    let missing = import_kindle_notebook(s, &path, Some(9_999), false).await;
    assert!(matches!(missing, Err(EngineError::NotFound(_))));
}

#[tokio::test]
async fn something_else_is_not_a_notebook() {
    let Some(path) = fixture("notebook/not-a-notebook.html") else {
        return;
    };
    let (tmp, e) = engine().await;
    let s = e.storage();
    let r = import_kindle_notebook(s, &path, None, false).await.unwrap();
    assert!(matches!(
        r.summary.diagnostics[..],
        [bookmole::Diagnostic {
            kind: DiagnosticKind::KindleNotebookUnreadable {
                class: ErrorClass::Parse,
                ..
            },
            ..
        }]
    ));
    let missing = import_kindle_notebook(s, &tmp.path().join("gone.html"), None, false)
        .await
        .unwrap();
    assert!(matches!(
        missing.summary.diagnostics[..],
        [bookmole::Diagnostic {
            kind: DiagnosticKind::KindleNotebookUnreadable {
                class: ErrorClass::Io,
                ..
            },
            ..
        }]
    ));
}

#[tokio::test]
async fn a_re_export_missing_a_highlight_removes_nothing() {
    let Some(path) = fixture("notebook/remains.html") else {
        return;
    };
    let (tmp, e) = engine().await;
    let s = e.storage();
    let book = add_book(s, "The Remains of the Day", "Kazuo Ishiguro").await;
    import_kindle_notebook(s, &path, Some(book), false)
        .await
        .unwrap();
    let n = rows(s, book, HighlightOrigin::KindleApp).await.len();

    let mut p = parse_notebook(&std::fs::read_to_string(&path).unwrap());
    // Deleted in the app: the highlight and the note that was on it.
    p.entries
        .retain(|e| !e.text.starts_with("A journey") && e.text != "pairs with the yellow one");
    let shorter = tmp.path().join("shorter.html");
    std::fs::write(
        &shorter,
        render_notebook("The Remains of the Day", &p.authors, &p.entries),
    )
    .unwrap();
    let r = import_kindle_notebook(s, &shorter, Some(book), false)
        .await
        .unwrap();
    assert_eq!(r.summary.removed, 0);
    assert_eq!(rows(s, book, HighlightOrigin::KindleApp).await.len(), n);
}

#[tokio::test]
async fn the_same_passage_from_the_kindle_and_its_app_stays_two_rows() {
    let (tmp, e) = engine().await;
    let s = e.storage();
    let book = add_book(s, "Kindred", "Octavia E. Butler").await;
    let passage = "The same words, read twice.";
    let clippings = tmp.path().join("My Clippings.txt");
    std::fs::write(
        &clippings,
        format!(
            "{KINDRED}\r\n- Your Highlight on Location 50-52 | Added on Monday, March 3, 2025 10:15:22 AM\r\n\r\n{passage}\r\n==========\r\n"
        ),
    )
    .unwrap();
    import_kindle_clippings(s, &clippings, false).await.unwrap();
    let mut p = parse_notebook(&format!(
        "<div class=\"bookTitle\">Kindred</div><div class=\"noteHeading\">Highlight(<span class=\"highlight_yellow\">yellow</span>) - Location 50</div><div class=\"noteText\">{passage}</div>"
    ));
    assert_eq!(p.entries.len(), 1);
    p.authors = vec!["Butler, Octavia E.".into()];
    let notebook = tmp.path().join("kindred.html");
    std::fs::write(
        &notebook,
        render_notebook("Kindred", &p.authors, &p.entries),
    )
    .unwrap();
    let r = import_kindle_notebook(s, &notebook, None, false)
        .await
        .unwrap();
    assert_eq!(r.book_id, Some(book));

    let all = e.list_highlights(book).await.unwrap();
    assert_eq!(all.len(), 2);
    let mut ids: Vec<i64> = all.iter().map(|h| h.id).collect();
    ids.sort_unstable();
    assert_eq!(same_passages(&all), vec![ids]);
    let mut origins: Vec<HighlightOrigin> = all.iter().map(|h| h.origin).collect();
    origins.sort_by_key(|o| o.as_str());
    assert_eq!(
        origins,
        vec![HighlightOrigin::Kindle, HighlightOrigin::KindleApp]
    );
}
